func sweepPipeline(p *Pipeline, metricName, paramName string) int {
    // validate metric
    objective := ""
    metricFound := false
    for _, stage := range p.Stages {
        for _, m := range stage.Metrics {
            if m.Name == metricName {
                metricFound = true
                objective = m.Objective
                break
            }
        }
        if metricFound { break }
    }
    if !metricFound {
        fmt.Fprintf(os.Stderr, "error: metric %s not found\n", metricName)
        return 1
    }
    // validate param
    paramFound := false
    for _, param := range p.Parameters {
        if param.Name == paramName {
            paramFound = true
            break
        }
    }
    if !paramFound {
        fmt.Fprintf(os.Stderr, "error: parameter %s not found\n", paramName)
        return 1
    }
    // group values
    groups := map[string][]float64{}
    for _, combo := range parameterCombinations(p) {
        id := experimentID(combo)
        metrics := collectExperimentMetrics(p, id)
        val, ok := metrics[metricName]
        if !ok { continue }
        valStr := asString(combo[paramName])
        groups[valStr] = append(groups[valStr], val)
    }
    if len(groups) == 0 {
        fmt.Fprintf(os.Stderr, "error: no experiments have metric %s\n", metricName)
        return 1
    }
    // sort group values
    values := make([]string, 0, len(groups))
    for v := range groups { values = append(values, v) }
    sort.Strings(values)
    // compute group stats and overall stats
    type groupOut struct {
        Value string `json:"value"`
        Count int `json:"count"`
        Mean float64 `json:"mean"`
        Std float64 `json:"std"`
        Min float64 `json:"min"`
        Max float64 `json:"max"`
    }
    groupStats := []groupOut{}
    var allValues []float64
    for _, v := range values {
        xs := groups[v]
        allValues = append(allValues, xs...)
        mean := computeMean(xs)
        std := sampleStd(xs)
        min, max := minMax(xs)
        groupStats = append(groupStats, groupOut{
            Value: v,
            Count: len(xs),
            Mean: round4(mean),
            Std: round4(std),
            Min: round4(min),
            Max: round4(max),
        })
    }
    // ANOVA
    var anovaF *float64
    if len(values) >= 2 && len(allValues) > len(values) {
        grandMean := computeMean(allValues)
        var between float64
        var within float64
        for _, v := range values {
            xs := groups[v]
            n := len(xs)
            mean := computeMean(xs)
            between += float64(n) * (mean - grandMean) * (mean - grandMean)
            within += float64(n-1) * sampleVariance(xs)
        }
        between /= float64(len(values) - 1)
        within /= float64(len(allValues) - len(values))
        if within > 0 {
            f := between / within
            anovaF = &f
        }
    }
    // best value
    bestValue := bestValue(values, groups, objective)
    // effect size
    var effectSize *float64
    if len(values) >= 2 && len(allValues) > len(values) {
        // compute within variance again or reuse
        if within > 0 {
            pooledStd := math.Sqrt(within)
            maxMean := computeMean(groups[values[0]])
            minMean := maxMean
            for _, v := range values {
                m := computeMean(groups[v])
                if m < minMean { minMean = m }
                if m > maxMean { maxMean = m }
            }
            es := (maxMean - minMean) / pooledStd
            es = round4(es)
            effectSize = &es
        }
    }
    // output
    out := struct {
        Parameter string `json:"parameter"`
        Metric string `json:"metric"`
        Objective string `json:"objective"`
        Groups []groupOut `json:"groups"`
        AnovaF *float64 `json:"anova_f"`
        BestValue string `json:"best_value"`
        EffectSize *float64 `json:"effect_size"`
    }{
        Parameter: paramName,
        Metric: metricName,
        Objective: objective,
        Groups: groupStats,
        AnovaF: anovaF,
        BestValue: bestValue,
        EffectSize: effectSize,
    }
    enc := json.NewEncoder(os.Stdout)
    enc.SetIndent("", "  ")
    if err := enc.Encode(out); err != nil { ... }
    return 0
}
```
