func reportPipeline(p *Pipeline) int {
	type reportExperiment struct {
		ID      string             `json:"id"`
		Metrics map[string]float64 `json:"metrics"`
		Stages  []StageState       `json:"stages"`
	}
	type reportOutput struct {
		Pipeline     string                       `json:"pipeline"`
		Experiments  []reportExperiment           `json:"experiments"`
		MetricSummary map[string]metricSummaryEntry `json:"metric_summary"`
	}
	out := reportOutput{Pipeline: p.Name, Experiments: []reportExperiment{}, MetricSummary: map[string]metricSummaryEntry{}}
	metricValues := map[string][]float64{}
	for _, combo := range parameterCombinations(p) {
		id := experimentID(combo)
		exp := reportExperiment{ID: id, Metrics: map[string]float64{}, Stages: []StageState{}}
		for _, stage := range p.Stages {
			if st, err := readStageState(id, stage.Name); err == nil {
				exp.Stages = append(exp.Stages, *st)
				for _, m := range st.Metrics {
					exp.Metrics[m.Name] = m.Value
					metricValues[m.Name] = append(metricValues[m.Name], m.Value)
				}
			}
		}
		out.Experiments = append(out.Experiments, exp)
	}
	for name, values := range metricValues {
		out.MetricSummary[name] = metricSummaryEntry{
			Count: len(values),
			Mean:  round4(meanValue(values)),
			Std:   round4(sampleStd(values)),
			Min:   round4(minValue(values)),
			Max:   round4(maxValue(values)),
		}
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	return 0
}
