func cmdSweep(args []string) int {
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe sweep <pipeline.yaml> --metric <name> --param <name>")
		return 1
	}
	pipelineFile := args[0]
	metricName := ""
	paramName := ""
	for i := 1; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--metric":
			if i+1 >= len(args) {
				fmt.Fprintln(os.Stderr, "error: --metric requires a value")
				return 1
			}
			i++
			metricName = args[i]
		case strings.HasPrefix(arg, "--metric="):
			metricName = strings.TrimPrefix(arg, "--metric=")
		case arg == "--param":
			if i+1 >= len(args) {
				fmt.Fprintln(os.Stderr, "error: --param requires a value")
				return 1
			}
			i++
			paramName = args[i]
		case strings.HasPrefix(arg, "--param="):
			paramName = strings.TrimPrefix(arg, "--param=")
		default:
			fmt.Fprintf(os.Stderr, "error: unknown argument %q\n", arg)
			return 1
		}
	}
	if metricName == "" || paramName == "" {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe sweep <pipeline.yaml> --metric <name> --param <name>")
		return 1
	}
	p, err := loadPipeline(pipelineFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	if errs := validatePipeline(p); len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintln(os.Stderr, e)
		}
		return 1
	}
	objective := ""
