	for _, stage := range p.Stages {
		for _, m := range stage.Metrics {
			if m.Name == metricName {
				metricFound = true
				if objective == "" {
					objective = m.Objective
				}
			}
		}
	}
	if !metricFound {
		fmt.Fprintf(os.Stderr, "error: metric %q not found in pipeline\n", metricName)
		return 1
	}
	paramFound := false
	for _, param := range p.Parameters {
