func sweepPipeline(p *Pipeline, metricName, paramName, objective string) int {
	type groupOut struct {
		Value string  `json:"value"`
		Count int     `json:"count"`
		Mean  float64 `json:"mean"`
		Std   float64 `json:"std"`
		Min   float64 `json:"min"`
		Max   float64 `json:"max"`
	}

	groupValues := map[string][]float64{}
	for _, combo := range parameterCombinations(p) {
		id := experimentID(combo)
		paramValue := asString(combo[paramName])
		metrics := map[string]float64{}
		for _, stage := range p.Stages {
			if st, err := readStageState(id, stage.Name); err == nil && st.Status == "completed" {
				for _, m := range st.Metrics {
					metrics[m.Name] = m.Value
				}
			}
		}
		if val, ok := metrics[metricName]; ok {
			groupValues[paramValue] = append(groupValues[paramValue], val)
		}
	}

	if len(groupValues) == 0 {
		fmt.Fprintf(os.Stderr, "error: metric %q not found in any completed experiment\n", metricName)
		return 1
	}

	values := make([]string, 0, len(groupValues))
	for v := range groupValues {
		values = append(values, v)
	}
	sort.Strings(values)

	groups := make([]groupOut, 0, len(values))
	groupMeans := map[string]float64{}
	groupVars := map[string]float64{}
	totalN := 0
	grandSum := 0.0
	for _, v := range values {
		obs := groupValues[v]
		n := len(obs)
		totalN += n
		mean := meanValue(obs)
		variance := 0.0
		if n > 1 {
			ss := 0.0
			for _, x := range obs {
				diff := x - mean
				ss += diff * diff
			}
			variance = ss / float64(n-1)
		}
		groupMeans[v] = mean
		groupVars[v] = variance
		grandSum += mean * float64(n)
		groups = append(groups, groupOut{
			Value: v,
			Count: n,
			Mean:  round4(mean),
			Std:   round4(math.Sqrt(variance)),
			Min:   round4(minValue(obs)),
			Max:   round4(maxValue(obs)),
		})
	}

	grandMean := 0.0
	if totalN > 0 {
		grandMean = grandSum / float64(totalN)
	}

	k := len(values)
	betweenVariance := 0.0
	withinVariance := 0.0
	if k > 1 && totalN > k {
		for _, v := range values {
			n := len(groupValues[v])
			diff := groupMeans[v] - grandMean
			betweenVariance += float64(n) * diff * diff
			withinVariance += float64(n-1) * groupVars[v]
		}
		betweenVariance /= float64(k - 1)
		withinVariance /= float64(totalN - k)
	}

